"<h3 style=\" margin-top:0px; margin-bottom:16px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px; line-height:125%;\"><a name=\"descriptions-for-the-settings\"></a><span style=\" font-size:large; font-weight:600;\">D</span><span style=\" font-size:large; font-weight:600;\">escriptions for the settings</span></h3>\n"
